    private static ContractRenderData SampleData(string ownerName = "王小明")
    {
        var owner = new Owner { OwnerId = "owner_r5", Name = ownerName, NationalId = "A123456789", Phone = "0912345678", Address = "桃園市桃園區慈文路322巷5號" };
        var pet = new Pet { PetId = "pet_r5", OwnerId = owner.OwnerId, Name = "小白", Species = "犬", Breed = "柴犬", Gender = "公", Age = "3 歲" };
        var appt = new Appointment { AppointmentId = "appt_r5", OwnerId = owner.OwnerId, PetId = pet.PetId, Date = new DateOnly(2026, 5, 16), Time = new TimeOnly(10, 0) };
        var rec = new GroomingRecord { GroomingRecordId = "rec_r5", AppointmentId = appt.AppointmentId, ServiceDate = appt.Date, ServiceTime = appt.Time };
        return new ContractRenderData(owner, pet, appt, rec, Array.Empty<byte>(), "安欣動物醫院", "03-3367775", "桃園市桃園區中福街60號");
    }

    // 從 HTML 提取緊接在某個標籤後的 <span class="blank wide"> 內容
    private static string ExtractBlankWideContent(string html, string labelPrefix)
    {
        var pattern = Regex.Escape(labelPrefix) + @"：<span class=""blank wide"">([^<]*)</span>";
        var m = Regex.Match(html, pattern);
        return m.Success ? m.Groups[1].Value : string.Empty;
    }

    [Fact(DisplayName = "R5 / 甲方簽章線不應帶入 Owner.Name")]
    public void Party_A_signature_line_does_not_contain_owner_name()
    {
        // Given
        var data = SampleData("王小明");
        var renderer = new ContractTemplateRenderer(_templatePath, _fontPath);

        // When
        var html = renderer.Render(data);

        // Then 甲方簽章 span 應為空白
        var partyAContent = ExtractBlankWideContent(html, "甲方簽章");
        partyAContent.Trim().Should().BeEmpty("甲方簽章 <span class=\"blank wide\"> 不應含 Owner.Name");
        html.Should().NotContain("甲方簽章：<span class=\"blank wide\">王小明</span>");
    }

