    [Fact(DisplayName = "R5 / 簽名日期維持系統帶入今日民國年月日")]
    public void Signature_date_filled_from_system_today()
    {
        // Given ServiceDate = 2026-05-16
        var data = SampleData();
        var renderer = new ContractTemplateRenderer(_templatePath, _fontPath);
        var html = renderer.Render(data);

        // Then HTML 應出現 "中華民國" 與 民國 115 / 5 / 16
        html.Should().Contain("中華民國");
        // 用 regex 取出 rocYear / rocMonth / rocDay
        var yearMatch = Regex.Match(html, @"中華民國.*?<span class=""blank"">(\d+)</span>\s*年", RegexOptions.Singleline);
        if (yearMatch.Success)
            yearMatch.Groups[1].Value.Should().Be("115", "民國年 = 2026 - 1911 = 115");
    }

    [Theory(DisplayName = "R5 / 不同飼主姓名下 4 個簽名線皆空白")]
